## Validation Invariants

```typescript
// Business rule validators — run at plan finalisation (BLUE phase gate)

function validatePlan(plan: WeeklyDinnerPlan): string[] {
  const errors: string[] = [];

  // Invariant 1: Budget ceiling
  const total = plan.meals.reduce(
    (sum, m) => sum + m.estimatedCostUSD, 0
  );
  if (total > 120) {
    errors.push(`Budget exceeded: $${total.toFixed(2)} > $120.00`);
  }

  // Invariant 2: All 7 days covered
  const days = new Set(plan.meals.map(m => m.day));
  const required = ['MON','TUE','WED','THU','FRI','SAT','SUN'];
  required.forEach(d => {
    if (!days.has(d as any)) errors.push(`Missing meal for ${d}`);
  });

  // Invariant 3: Distinct recipe names
  const names = plan.meals.map(m => m.recipeName.toLowerCase().trim());
  const uniqueNames = new Set(names);
  if (uniqueNames.size < 7) {
    errors.push('Duplicate recipe names detected — all 7 meals must be distinct.');
  }

  // Invariant 4: Servings always 4
  plan.meals.forEach(m => {
    if (m.servings !== 4) {
      errors.push(`${m.recipeName}: servings must be 4, got ${m.servings}`);
    }
  });

  // Invariant 5: Cost consistency
  plan.meals.forEach(m => {
    const ingredientTotal = m.ingredients.reduce(
      (sum, i) => sum + i.estimatedCostUSD, 0
    );
    const delta = Math.abs(ingredientTotal - m.estimatedCostUSD);
    if (delta > 0.02) { // 2-cent tolerance for float rounding
      errors.push(
        `${m.recipeName}: declared cost $${m.estimatedCostUSD} \
         ≠ ingredient sum $${ingredientTotal.toFixed(2)}`
      );
    }
  });

  return errors;
}
```

