## API Surface (if productised)

```typescript
// Minimal REST surface for a software implementation

// POST /plans
// Create a new weekly plan draft
type CreatePlanRequest = {
  householdSize: 4;
  budgetCeilingUSD: 120;
  pantryAssumptions: PantryItem[];
  dietaryConstraints?: string[]; // free text, surfaced not enforced
};
type CreatePlanResponse = { planId: string; status: 'DRAFT' };

// PUT /plans/:planId/meals/:day
// Assign or update a meal slot
type UpsertMealRequest = Omit<MealSlot, 'day'>;
type UpsertMealResponse = { slot: MealSlot; runningTotalUSD: number };

// GET /plans/:planId/shopping-list
// Returns deduplicated, department-sorted shopping list
type ShoppingListResponse = {
  items: (Ingredient & { meals: string[] })[]; // meals that use this item
  totalEstimatedCostUSD: number;
};

// POST /plans/:planId/validate
// Runs all BLUE-phase invariants
type ValidateResponse = {
  valid: boolean;
  errors: string[];
  totalEstimatedCostUSD: number;
  allergenSummary: WeeklyDinnerPlan['allergenDisclosureSummary'];
};

// POST /plans/:planId/approve
// Records household sign-off
type ApproveRequest = { approvedBy: string };
type ApproveResponse = { planId: string; status: 'APPROVED'; approvedAt: string };
```

